-- Additive ECG subsystem. Application DB role alone may access these tables.
create table if not exists devices (id uuid primary key, model text, firmware_version text, sample_rate_hz integer check (sample_rate_hz between 1 and 2000), units text check (units in ('raw','mV')), status text not null default 'unpaired' check (status in ('unpaired','paired','revoked')), last_seen_at timestamptz, created_at timestamptz not null default now());
create table if not exists device_credentials (device_id uuid primary key references devices(id), secret_hash text not null, rotated_at timestamptz not null default now(), revoked_at timestamptz);
create table if not exists device_pairing_challenges (id uuid primary key, patient_id text not null references app_users(id), code_hash text not null, expires_at timestamptz not null, consumed_at timestamptz, created_at timestamptz not null default now());
create table if not exists patient_device_assignments (device_id uuid primary key references devices(id), patient_id text not null references app_users(id), assigned_at timestamptz not null default now(), unpaired_at timestamptz);
create index if not exists ecg_assignments_patient on patient_device_assignments(patient_id) where unpaired_at is null;
create table if not exists ecg_recording_sessions (id uuid primary key, patient_id text not null references app_users(id), device_id uuid not null references devices(id), status text not null check (status in ('created','starting','recording','interrupted','finalizing','completed','failed')), started_at timestamptz not null default now(), ended_at timestamptz, last_sequence bigint not null default -1, sample_count bigint not null default 0, sample_rate_hz integer not null, units text not null, last_sample_at timestamptz, unique(id,device_id));
create index if not exists ecg_sessions_patient_started on ecg_recording_sessions(patient_id,started_at desc);
create unique index if not exists ecg_one_active_session on ecg_recording_sessions(device_id) where status in ('created','starting','recording','interrupted','finalizing');
create table if not exists ecg_recording_chunks (session_id uuid not null references ecg_recording_sessions(id), sequence bigint not null, first_sample_at timestamptz not null, sample_count integer not null, samples jsonb not null, sha256 text not null, created_at timestamptz not null default now(), primary key(session_id,sequence));
create table if not exists ecg_session_notes (id uuid primary key, session_id uuid not null references ecg_recording_sessions(id), patient_id text not null references app_users(id), note text not null check (length(note) between 1 and 1000), created_at timestamptz not null default now());
create table if not exists ecg_session_events (id uuid primary key, session_id uuid references ecg_recording_sessions(id), event text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists device_audit_logs (id uuid primary key, device_id uuid references devices(id), patient_id text references app_users(id), action text not null, created_at timestamptz not null default now());
-- Supabase Data API roles must not read privileged direct-pg ECG tables.
do $$ begin if exists(select 1 from pg_roles where rolname='anon') then revoke all on devices,device_credentials,device_pairing_challenges,patient_device_assignments,ecg_recording_sessions,ecg_recording_chunks,ecg_session_notes,ecg_session_events,device_audit_logs from anon; end if; if exists(select 1 from pg_roles where rolname='authenticated') then revoke all on devices,device_credentials,device_pairing_challenges,patient_device_assignments,ecg_recording_sessions,ecg_recording_chunks,ecg_session_notes,ecg_session_events,device_audit_logs from authenticated; end if; end $$;
